INSERT INTO seat_inventory (id, tenant_id, trip_id, seat_number, status, held_until, booked_at)
SELECT 
    gen_random_uuid(),
    t.tenant_id,
    t.id,
    r.row_num::text || c.col,
    CASE 
        WHEN ((('x' || substr(md5(t.id::text || r.row_num::text || c.col), 1, 4))::bit(16)::int % 100) < 55) THEN 'BOOKED'
        WHEN ((('x' || substr(md5(t.id::text || r.row_num::text || c.col), 1, 4))::bit(16)::int % 100) < 65) THEN 'HELD'
        ELSE 'AVAILABLE'
    END,
    CASE 
        WHEN ((('x' || substr(md5(t.id::text || r.row_num::text || c.col), 1, 4))::bit(16)::int % 100) BETWEEN 55 AND 64) THEN NOW() + INTERVAL '8 minutes'
        ELSE NULL
    END,
    CASE 
        WHEN ((('x' || substr(md5(t.id::text || r.row_num::text || c.col), 1, 4))::bit(16)::int % 100) < 55) THEN NOW() - INTERVAL '12 minutes'
        ELSE NULL
    END
FROM trips t
CROSS JOIN generate_series(1, 10) AS r(row_num)
CROSS JOIN (VALUES ('A'), ('B'), ('C'), ('D')) AS c(col)
WHERE t.id IN (
    '11111111-0004-0001-0000-000000000001',
    '22222222-0004-0001-0000-000000000001',
    '33333333-0004-0001-0000-000000000001',
    '44444444-0004-0001-0000-000000000001',
    '55555555-0004-0001-0000-000000000001',
    '66666666-0004-0001-0000-000000000001',
    '77777777-0004-0001-0000-000000000001'
)
ON CONFLICT (trip_id, seat_number) DO UPDATE SET 
    status = EXCLUDED.status, 
    held_until = EXCLUDED.held_until, 
    booked_at = EXCLUDED.booked_at;

